import math

def gcd_three(a, b, c):
    return math.gcd(a, math.gcd(b, c))

def solve():
    good_numbers = set()

    # Increased search limit for u3 to find the 20th smallest number
    MAX_U3 = 60 

    for u1 in range(1, MAX_U3 // 3 + 1):
        for u2 in range(u1 + 1, MAX_U3 // 2 + 1):

            # u3 must divide u1*u2, so u3 <= u1*u2.
            # Also u3 <= MAX_U3.
            upper_bound_u3 = min(MAX_U3, u1 * u2)

            for u3 in range(u2 + 1, upper_bound_u3 + 1):
                # Condition 1: gcd(u1, u2, u3) = 1
                if gcd_three(u1, u2, u3) != 1:
                    continue

                # Condition 2: u3 | u1*u2
                if (u1 * u2) % u3 != 0:
                    continue

                # Condition 3: u2 | u1*u3
                if (u1 * u3) % u2 != 0:
                    continue

                # Condition 4: u1 | u2*u3
                if (u2 * u3) % u1 != 0:
                    continue

                m = u1 * u2 * u3
                good_numbers.add(m)

    # Get the sorted list of unique good numbers
    sorted_good_numbers = sorted(list(good_numbers))

    print(f"Found {len(sorted_good_numbers)} distinct good numbers up to MAX_U3={MAX_U3}.")

    # Check if we found at least 20
    if len(sorted_good_numbers) >= 20:
        print(f"The 20th smallest good number is: {sorted_good_numbers[19]}")
    else:
        print(f"Only found {len(sorted_good_numbers)} numbers. Further search needed.")

solve()

import math
from itertools import product

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_good_numbers():
    candidates = set()

    # We need at least 25 candidates, but let's iterate up to C=30 to be safe 
    # and ensure we find the 20th smallest reliably.
    MAX_C = 30

    for C in range(1, MAX_C + 1):
        for B in range(1, C + 1):
            if gcd(B, C) != 1:
                continue

            for A in range(1, B + 1):
                if gcd(A, B) != 1 or gcd(A, C) != 1:
                    continue

                # Check if A, B, C are pairwise coprime. The inner checks cover this.
                # (A, B) coprime, (A, C) coprime, (B, C) coprime.

                m = (A**2) * (B**2) * (C**2)
                candidates.add(m)

    sorted_candidates = sorted(list(candidates))

    print(f"Total candidates found: {len(sorted_candidates)}")
    print("First 25 candidates:")
    for i in range(min(25, len(sorted_candidates))):
        print(f"Rank {i+1}: {sorted_candidates[i]}")

    if len(sorted_candidates) >= 20:
        print(f"The 20th smallest candidate is: {sorted_candidates[19]}")
    else:
        print("Not enough candidates found.")

generate_good_numbers()
